class Solution { fun subdomainVisits(cpdomains:Array<String>):List<String>{val counts=sortedMapOf<String,Int>();for(item in cpdomains){val space=item.indexOf(' ');val count=item.substring(0,space).toInt();var domain=item.substring(space+1);while(true){counts[domain]=(counts[domain]?:0)+count;val dot=domain.indexOf('.');if(dot<0)break;domain=domain.substring(dot+1)}};return counts.map{(domain,count)->"$count $domain"}} }
